  ('dc889a97-96eb-482b-bc2d-8fa74833983e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सूर््य पानी की सतह के पास पहुँच गयया था। सुनहली किरणों ने पीली रेत को एक नयया-सा रंग दे दियया था। उस रंग में रेत इस तरह चमक रही थी जैसे अभी-अभी उसका निर््ममाण करके उसे वहाँ उड़ेला गयया हो। मैंने उस रेत पर दूर तक बने अपने पैरों के निशानों को देखा। लगा जैसे रेत पहली बार उन निशानों से टूटा हो। इससे मन में एक सिहरन भी हुई, हल्की उदासी भी घिर आई।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c575c195-ceaf-44f5-a753-60a758a637ea', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सूर््य का गोला पानी की सतह से छू गयया। पानी पर दूर तक सोना-ही-सोना ढुल आयया। पर वह रंग इतनी जल्दी-जल्दी बदल रहा था कि किसी भी एक क्षण के लिए उसे एक नाम दे सकना असंभव था। सूर््य का गोला जैसे एक बेबसी में पानी के लावे में डूबता जा रहा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('94f1a230-7e2a-4fe9-b361-b9de87d85d49', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$धीरे-धीरे वह पूरा डूब गयया और कुछ क्षण पहले जहाँ सोना बह रहा था, वहाँ अब लहू बहता नजर आने लगा। कुछ और क्षण बीतने पर वह लहू भी धीरे-धीरे बैज़नी और बैज़नी से काला पड़ गयया। मैंने फिर एक बार मुड़कर दाइ« तरफ पीछे देख लियया। नारियलोों की टहनिययाँ उसी तरह हवा में ऊपर उठठी थीं। हवा उसी तरह गूँज रही थी, पर पूरे दृश््यपट पर स््ययाही फैल गई थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ca3ef7c5-e337-4661-b8a6-7b60d73484c7', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक-दूसरे से दूर खड़े झुरमुट, स््ययाह पड़कर, जैसे लगातार सिर धुन रहे थे और हाथ-पैर पटक रहे थे। मैं अपनी जगह से उठठ खड़ा हुआ और अपनी मुि‍ट्‍ठययाँ भींचता-खोलता कभी उस तरफ और कभी समुद्र की तरफ देखता रहा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d3104074-f4f8-435b-adae-a840803e756e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अचानक खययाल आयया कि मुझे वहाँ से लौटकर भी जाना है। इस खययाल से ही शरीर में कँपकँपी भर गई। दूर सैंड हिल की तरफ देखा। वहाँ स््ययाही में डूबे कुछ धुँधले रंग हिलते नजर आ रहे थे। मैंने रंगों को पहचानने की कोशिश की, पर उतनी दूर से आकृतियोों को अलग-अलग कर सकना संभव नहीं था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('799a0d03-7592-4ec9-b3c2-303fe4267330', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे और उन रंगों के बीच स््ययाह पड़ती रेत के कितने ही टीले थे। मन में डर समाने लगा कि क््या अँधेरा होने से पहले मैं उन सब टीलों को पार करके जा सकूँगा? कुछ कदम उस तरफ बढ़ा भी पर लगा कि नहीं! उस रास्ते से जाऊँगा, तो शाययद रेत में ही भटकता रह जाऊँगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
