  ('cac70962-d914-4110-a83f-736fa8887313', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अपने प्रययत्न की सार््थकता से संतुष्ट होकर मैं टीले पर बैठठ गयया— ऐसे जैसे वह टीला संसार की सबसे ऊँची चोटी हो, और मैंने, सिर््फ मैंने, उस चोटी को पहली बार सर कियया हो।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5059bc00-a42d-48ad-b1c9-fa2cce91912d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पीछे दाइ« तरफ दूर-दूर हटकर उगे नारियलोों के झुरमुट नजर आ रहे थे। गूँजती हुई तेज हवा से उनकी टहनिययाँ ऊपर को उठठ रही थीं। पच्छछिमी तट के साथ-साथ सूखी पहाड़़ियों की एक ćृंखला दूर तक चली गई थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1b08ed18-824e-4597-9a52-97ea99eb6df5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पच्छछिमी तट के साथ-साथ सूखी पहाड़़ियों की एक ćृंखला दूर तक चली गई थी जो सामने फैली रेत के कारण बहुत रूखी, बीहड़ और वीरान लग रही थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f2e04aee-8da2-4f8c-aa6d-486343f15090', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सूर््य पानी की सतह के पास पहुँच गयया था। सुनहली किरणों ने पीली रेत को एक नयया-सा रंग दे दियया था। उस रंग में रेत इस तरह चमक रही थी जैसे अभी-अभी उसका निर््ममाण करके उसे वहाँ उड़ेला गयया हो। मैंने उस रेत पर दूर तक बने अपने पैरों के निशानों को देखा। लगा जैसे रेत पहली बार उन निशानों से टूटा हो। इससे मन में एक सिहरन भी हुई, हल्की उदासी भी घिर आई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6377c764-e047-43c6-9159-21f6b3244d74', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सूर््य का गोला पानी की सतह से छू गयया। पानी पर दूर तक सोना-ही-सोना ढुल आयया। पर वह रंग इतनी जल्दी-जल्दी बदल रहा था कि किसी भी एक क्षण के लिए उसे एक नाम दे सकना असंभव था। सूर््य का गोला जैसे एक बेबसी में पानी के लावे में डूबता जा रहा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7427f090-6ad2-4cab-a356-e5964ddf11fd', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$धीरे-धीरे वह पूरा डूब गयया और कुछ क्षण पहले जहाँ सोना बह रहा था, वहाँ अब लहू बहता नजर आने लगा। कुछ और क्षण बीतने पर वह लहू भी धीरे-धीरे बैज़नी और बैज़नी से काला पड़ गयया। मैंने फिर एक बार मुड़कर दाइ« तरफ पीछे देख लियया। नारियलोों की टहनिययाँ उसी तरह हवा में ऊपर उठठी थीं। हवा उसी तरह गूँज रही थी, पर पूरे दृश््यपट पर स््ययाही फैल गई थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8a03877a-4c52-43eb-8f04-3b9ed0113fd1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक-दूसरे से दूर खड़े झुरमुट, स््ययाह पड़कर, जैसे लगातार सिर धुन रहे थे और हाथ-पैर पटक रहे थे। मैं अपनी जगह से उठठ खड़ा हुआ और अपनी मुि‍ट्‍ठययाँ भींचता-खोलता कभी उस तरफ और कभी समुद्र की तरफ देखता रहा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ec8c0be6-4e5c-4da5-9f37-d2d79c41aa3c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अचानक खययाल आयया कि मुझे वहाँ से लौटकर भी जाना है। इस खययाल से ही शरीर में कँपकँपी भर गई। दूर सैंड हिल की तरफ देखा। वहाँ स््ययाही में डूबे कुछ धुँधले रंग हिलते नजर आ रहे थे। मैंने रंगों को पहचानने की कोशिश की, पर उतनी दूर से आकृतियोों को अलग-अलग कर सकना संभव नहीं था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ad9a736d-ad31-4c8b-a147-1fdbd46e1dbf', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे और उन रंगों के बीच स््ययाह पड़ती रेत के कितने ही टीले थे। मन में डर समाने लगा कि क््या अँधेरा होने से पहले मैं उन सब टीलों को पार करके जा सकूँगा? कुछ कदम उस तरफ बढ़ा भी पर लगा कि नहीं! उस रास्ते से जाऊँगा, तो शाययद रेत में ही भटकता रह जाऊँगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fd0755f3-f0ae-4029-bcc8-0a4d17421fb8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इसलिए सोचा बेहतर है नीचे समुद्र तट पर उतर जाऊँ— तट का रास्ता निश्‍च‍ित रूप से केप होटल के सामने तक ले जाएगा। निर््णयय तुरंत करना था, इसलिए बिना और सोचे मैं रेत पर बैठठकर नीचे तट की तरफ फिसल गयया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e685b71b-9fb8-4c58-aee6-42c573e6c6d9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर तट पर पहुँचकर फिर कुछ क्षण बढ़ते अँधेरे की बात भूला रहा। कारण था तट की रेत। ययूँ पहले भी समुद्र-तट पर कई-कई रंगों की रेत देखी थी— सुरमई, खाकी, पीली और लाल।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5154a7a6-8b42-4503-b370-0a878991d7aa', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मगर जैसे रंग उस रेत में थे, वैसे मैंने पहले कभी कहीं की रेत में नहीं देखे थे। कितने ही अनाम रंग थे वे। एक-एक इंच पर एक-दूसरे से अलग... और एक-एक रंग कई-कई रंगों की झलक लिए हुए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('465ae327-3ed9-45f8-9e58-3a9906c9f17c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$काली घटा और घनी लाल आँधी को मिलाकर रेत के आकार में ढाल देने से रंगों के जितनी तरह के अलग-अलग सम््ममिश्रण पाए जा सकते थे, वे सब वहाँ थे— और उनके अतिरिक्‍त भी बहुत-से$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9abece96-eba2-42d8-a235-b2f54a293bd8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सूर््य का गोला पानी की सतह से छू गयया। पानी पर दूर तक सोना-ही-सोना ढुल आयया। पर वह रंग इतनी जल्दी-जल्दी बदल रहा था कि किसी भी एक क्षण के लिए उसे एक नाम दे सकना असंभव था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6f36062d-b337-4d85-a7dc-aacc1c11a637', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने उस रेत पर दूर तक बने अपने पैरों के निशानों को देखा। लगा जैसे रेत पहली बार उन निशानों से टूटा हो। इससे मन में एक सिहरन भी हुई, हल्की उदासी भी घिर आई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
