  ('21b969bf-1189-4307-817d-5a99edf74de5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने फिर एक बार मुड़कर दाइ« तरफ पीछे देख लियया। नारियलोों की टहनिययाँ उसी तरह हवा में ऊपर उठठी थीं। हवा उसी तरह गूँज रही थी, पर पूरे दृश््यपट पर स््ययाही फैल गई थी। एक-दूसरे से दूर खड़े झुरमुट, स््ययाह पड़कर, जैसे लगातार सिर धुन रहे थे और हाथ-पैर पटक रहे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e6e07608-84ca-408c-a2a6-dd00947f81b0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रंग थे। मैंने कई अलग-अलग रंगों की रेत को हाथ में लेकर देखा और मसलकर नीचे गिर जाने दियया। जिन रंगों को हाथों से नहीं छू सका, उन््हें पैरों से मसल दियया। मन था कि किसी तरह हर रंग की थोड़ी-थोड़ी रेत अपने पास रख लूँ। पर उसका कोई उपायय नहीं था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('58ef6adf-8048-4545-9a9e-77ddcdbf9039', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यह सोचकर कि फिर किसी दिन आकर उस रेत को बटोरूँगा, मैं उदास मन से वहाँ से आगे चल दियया। समुद्र में पानी बढ़ रहा था। तट की चौड़ाई धीरे-धीरे कम होती जा रही थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('47c87983-e276-457f-a29c-6c2660472366', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक लहर मेरे पैरों को भिगो गई, तो सहसा मुझे खतरे का एहसास हुआ। मैं जल्दी-जल्दी चलने लगा। तट का सिर््फ तीन-तीन चार-चार फुट हिस्सा पानी से बाहर था। लग रहा था कि जल्दी ही पानी उसे भी अपने अंदर समा लेगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2ca0722c-547d-4ece-ab0e-f6c55a75cfad', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक बार सोचा कि खड़ी रेत से होकर फिर ऊपर चला जाऊँ। पर वह स््ययाह पड़ती रेत इस तरह दीवार की तरह उठठी थी कि उस रास्ते ऊपर जाने की कोशिश करना ही बेकार था। मेरे मन में खतरा बढ़ गयया। मैं दौड़ने लगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
