  ('4ede92f1-2949-4321-8692-589bea674e58', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रात केप होटल का लॉन। अँधेरे में हिंद महासागर को काटती कुछ स््ययाह लकीरें— एक पौधे की टहनिययाँ। नीचे सड़क पर टार््च जलाता-बुझाता एक आदमी। दक्षिण-पूर््व के क्षितिज में एक जहाज की मद्धिम-सी रोशनी। सूर्योदयय। हम आठठ आदमी ‘विवेकानंद चट्टान’ पर बैठठे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('990b910d-cd6a-4b3f-8f01-dc635a7b22d1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$चट्टान तट से सौ-सवा-सौ गज आगे समुद्र के बीच जाकर है— वहाँ, जहाँ बंगाल की खाड़ी की भौगोलिक सीमा समाप्त होती है। मेरे अलावा कन््याकुमारी के तीन नवययुवक थे जिनमें से एक ग्रेजुएट था। चार मल््ललाह थे जो एक छोटी-सी मछुआ नाव में हमें वहाँ लाए थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4903589d-6617-4997-bc76-340a29780943', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नाव क््या थी, रबड़ पेड़ के तीन तनों को साथ-साथ जोड़ लियया गयया था, बस। नीचे की नुकीली चट्टानों और ऊपर की ऊँची-ऊँची लहरों से बचाते हुए मल््ललाह नाव को उस तरफ ला रहे थे, तो मैंने आसमान की तरफ देखते हुए उतनी देर अपनी चेतना को स््थगित रखने की चेष्टा की थी, अपने अंदर के डर को दिखावटी उदासीनता से ढक रखना चाहा था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('301c125d-5504-4f9a-af86-ed4f7b67e892', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पर जब चट्टान पर पहुँच गए, तो डर मेरी टाँगों में उतर गयया क््योोंकि वहाँ बैठठे हुए भी वे हल्के-हल्के काँप रही थीं। ग्रेजुएट नवययुवक मुझे बता रहा था कि कन््याकुमारी की आठठ हजार की आबादी में कम-से-कम चार-पाँच सौ शिक्षित नवययुवक ऐसे हैं जो बेकार हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7344429d-f2ef-4454-8b42-9238454c408c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनमें से सौ के लगभग ग्रेजुएट हैं। उनका मुख््य धंधा है नौकरियोों के लिए अर््ज़़िययाँ देना और बैठठकर आपस में बहस करना। वह खुद वहाँ फोटो-एल्बम बेचता था। दूसरे नवययुवक भी उसी तरह के छोटे-मोटे काम करते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4fbbeb61-0580-4184-9b97-427967f878d9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$“हम लोग सीपियोों का गूदा खाते हैं और दार््शनिक सिद््धाांतों पर बहस करते हैं”, वह कह रहा था। “इस चट्टान से इतनी प्रेरणा तो हमें मिलती ही है।” मुझे दिखाने के लिए उसने वहीं से एक सीपी लेकर उसे तोड़ा और उसका गूदा मुँह में डाल लियया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('80bc3c63-130f-46b5-9e3e-4da0b5c38c18', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पानी और आकाश में तरह-तरह के रंग झिलमिलाकर, छोटे-छोटे द्वीपों की तरह समुद्र में बिखरी स््ययाह चट्टानों की ओट से सूर््य उदित हो रहा था। घाट पर बहुत-से लोग उगते सूर््य को अघ्‍यर् देने के लिए एकत्रित थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7e222337-b4b4-4501-9c8c-406262758a59', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$घाट से थोड़ा हटकर गवर््नमेंट गेस्ट हाउस के बैरे सरकारी मेहमानों को सूर्योदयय के समयय की कॉफी पिला रहे थे। दो स्थानीयय नवययुवतिययाँ उन््हें अपनी टोकरियोों से शंख और मालाएँ दिखला रही थीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
