  ('b8349a77-3f36-41c9-8912-0872cc3bbaac', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हम आठठ आदमी ‘विवेकानंद चट्टान’ पर बैठठे थे। चट्टान तट से सौ-सवा-सौ गज आगे समुद्र के बीच जाकर है— वहाँ, जहाँ बंगाल की खाड़ी की भौगोलिक सीमा समाप्त होती है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
