  ('26f30fc6-240b-4a03-ac1f-097308bb9d93', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सूर्योदयय। हम आठठ आदमी ‘विवेकानंद चट्टान’ पर बैठठे थे। चट्टान तट से सौ-सवा-सौ गज आगे समुद्र के बीच जाकर है— वहाँ, जहाँ बंगाल की खाड़ी की भौगोलिक सीमा समाप्त होती है। मेरे अलावा कन््याकुमारी के तीन नवययुवक थे जिनमें से एक ग्रेजुएट था। चार मल््ललाह थे जो एक छोटी-सी मछुआ नाव में हमें वहाँ लाए थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('020a9efc-db71-403e-abb6-f73c16099ac8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पानी और आकाश में तरह-तरह के रंग झilमिलाकर, छोटे-छोटे द्वीपों की तरह समुद्र में बिखरी स््ययाह चट्टानों की ओट से सूर््य उदित हो रहा था। घाट पर बहुत-से लोग उगते सूर््य को अघ्‍यर् देने के लिए एकत्रित थे। घाट से थोड़ा हटकर गवर््नमेंट गेस्ट हाउस के बैरे सरकारी मेहमानों को सूर्योदयय के समयय की कॉफी पिला रहे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2b63ac83-e19e-45e2-9349-726ea9822408', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सूर्य-दर्शन। मेरा साथी अब मुहल्ले-मुहल्ले के हिसाब से मुझे बेकारी के आँकड़े बता रहा था। बहुत-से कडल-काक हमारे आस-पास तैर रहे थे— वहाँ की बेकारी की समस्या और सूर्योदय की विशेषता, इन दोनों से बे-लाग।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('16caceeb-e07b-4b75-adb9-c6604bbc70c0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कन्याकुमारी के मंदिर में पूजा की घंटियाँ बज रही थीं। भक्तों की एक मंडली अंदर जाने से पहले मंदिर की दीवार के पास रुककर उसे प्रणाम कर रही थी। सरकारी मेहमान गेस्ट-हाउस की तरफ लौट रहे थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6c054c48-8265-4da8-83bc-96419370bde3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '7135be3a-1dc9-4b26-b22c-93ee288b024e', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारी नाव और किनारे के बीच हल्की धूप में कई एक नावों के पाल और कडल-काकों के पंख एक-से चमक रहे थे। मैं अब भी आँखों से बीच की दूरी नाप रहा था और मन में बसों का टाइम-टेबल दोहरा रहा था। तीसरी बस नौ चालीस पर, चौथी...।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-13T07-35-12-158Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
